import{_ as s,o as e,c as t,a0 as n}from"./chunks/framework.BpJS36ta.js";const h=JSON.parse('{"title":"Fs","description":"","frontmatter":{},"headers":[],"relativePath":"modules/syntax/fs.md","filePath":"modules/syntax/fs.md"}'),p={name:"modules/syntax/fs.md"};function i(o,a,l,u,r,c){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="fs" tabindex="-1">Fs <a class="header-anchor" href="#fs" aria-label="Permalink to &quot;Fs&quot;">​</a></h1><p>Modul <code>fs</code> menyediakan operasi filesystem: baca/tulis file, baris, path helper, copy/move. Level primitive dibawa dari modul native <code>fsbase</code>, level tinggi ditulis murni dengan bahasa Rupa.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import fs from rupa</span></span></code></pre></div><h2 id="baca-tulis" tabindex="-1">Baca &amp; tulis <a class="header-anchor" href="#baca-tulis" aria-label="Permalink to &quot;Baca &amp; tulis&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fs.write(&quot;data.txt&quot;, &quot;hello\\n&quot;)</span></span>
<span class="line"><span>text = fs.read(&quot;data.txt&quot;)</span></span>
<span class="line"><span>print(text)</span></span>
<span class="line"><span>// hello</span></span></code></pre></div><p><code>fs.read()</code> membaca seluruh isi file sebagai string. <code>fs.write()</code> menimpa isi file.</p><h3 id="append" tabindex="-1">Append <a class="header-anchor" href="#append" aria-label="Permalink to &quot;Append&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fs.append(&quot;log.txt&quot;, &quot;baris baru\\n&quot;)</span></span></code></pre></div><h2 id="baris" tabindex="-1">Baris <a class="header-anchor" href="#baris" aria-label="Permalink to &quot;Baris&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lines = fs.readLines(&quot;data.txt&quot;)</span></span>
<span class="line"><span>print(lines)</span></span>
<span class="line"><span>// [&quot;hello&quot;, &quot;world&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fs.writeLines(&quot;out.txt&quot;, [&quot;a&quot;, &quot;b&quot;])</span></span>
<span class="line"><span>// out.txt berisi &quot;a\\nb\\n&quot;</span></span></code></pre></div><h2 id="path-helper" tabindex="-1">Path helper <a class="header-anchor" href="#path-helper" aria-label="Permalink to &quot;Path helper&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(fs.base(&quot;a/b/c.txt&quot;))  // c.txt</span></span>
<span class="line"><span>print(fs.dir(&quot;a/b/c.txt&quot;))   // a/b</span></span>
<span class="line"><span>print(fs.ext(&quot;a/b/c.txt&quot;))   // txt</span></span>
<span class="line"><span>print(fs.join(&quot;a&quot;, &quot;b.txt&quot;)) // a/b.txt</span></span></code></pre></div><h2 id="copy-move-remove" tabindex="-1">Copy, move, remove <a class="header-anchor" href="#copy-move-remove" aria-label="Permalink to &quot;Copy, move, remove&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fs.copy(&quot;a.txt&quot;, &quot;b.txt&quot;)    // true jika sukses</span></span>
<span class="line"><span>fs.move(&quot;b.txt&quot;, &quot;c.txt&quot;)    // copy + remove sumber</span></span>
<span class="line"><span>fs.remove(&quot;c.txt&quot;)           // true jika sukses</span></span></code></pre></div><h2 id="info-file" tabindex="-1">Info file <a class="header-anchor" href="#info-file" aria-label="Permalink to &quot;Info file&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(fs.exists(&quot;a.txt&quot;))  // true/false</span></span>
<span class="line"><span>print(fs.size(&quot;a.txt&quot;))    // ukuran byte, -1 jika tidak ada</span></span>
<span class="line"><span>print(fs.isDir(&quot;.&quot;))       // true jika direktori</span></span></code></pre></div>`,16)])])}const b=s(p,[["render",i]]);export{h as __pageData,b as default};
